                % Unpack the gain params.
                c1 = gain_params{ 1 };
                c3 = gain_params{ 2 };
                delta = gain_params{ 3 };
                R1 = gain_params{ 4 };
                R2 = gain_params{ 5 };
                
                % Compute the gain c2.
                c2 = self.network_utilities.compute_absolute_division_c2( c1, c3, delta, R1, R2 );
                
            elseif strcmpi( encoding_scheme, 'relative' )               % If the encoding scheme is 'relative'...
                
