                c3 = gain_params{ 1 };
                delta = gain_params{ 2 };
                R3 = gain_params{ 3 };
                
                % Compute the gains c1 & c2.
                [ c1, c2 ] = self.network_utilities.compute_relative_division_gains( c3, delta, R3 );
                
            else                                                        % Otherwise...
                
                % Throw an error.
                error( 'Unrecognized encoding scheme.' )
                
            end
            
        end
        
        
