        % ---------- Inversion Subnetwork Functions ----------
        
        % Implement a function to pack the formulation params for an absolute inversion subnetwork.
        function formulation_input_params = pack_absolute_inversion_formulation_params( self, c1, c3, delta, x1_max )
        
            % Set the default input params.
            if nargin < 5, x1_max = self.x1max_absolute_inversion_DEFAULT; end
            if nargin < 4, delta = self.delta_absolute_inversion_DEFUALT; end
            if nargin < 3, c3 = self.c3_absolute_inversion_DEFAULT; end
            if nargin < 2, c1 = self.c1_absolute_inversion_DEFAULT; end
            
            % Pack the params.
            formulation_input_params.c1 = c1;
            formulation_input_params.c3 = c3;
            formulation_input_params.delta = delta;
            formulation_input_params.x1_max = x1_max;
            
        end
        
        
