        % Implement a function to unpack the input params for an absolute transmission subnetwork.  
        function [ c, x1_max, Gm1, Gm2, Cm1, Cm2 ] = unpack_absolute_transmission_input_params( self, transmission_input_params, neuron_manager, undetected_option )
            
            % Set the default input arguments.
            if nargin < 4, undetected_option = self.undetected_option_DEFAULT; end
            if nargin < 3, neuron_manager = self.neuron_manager; end
