        % Implement a function to convert transmission params to formulation params.
        function formulation_input_params = transmission_input_params2formulation_input_params( self, transmission_input_params, encoding_scheme, neuron_manager, undetected_option )
            
            % Set the default input arguments.
            if nargin < 5, undetected_option = self.undetected_option_DEFAULT; end
            if nargin < 4, neuron_manager = self.neuron_manager; end
            if nargin < 3, encoding_scheme = 'absolute'; end
            if nargin < 2, transmission_input_params = struct( [  ] ); end
            
            % Determine how to perform the parameter conversion.
            if strcmpi( encoding_scheme, 'absolute' )                       % If the encoding scheme is 'absolute'...
                
                % Unpack the absolute transmission params.
                [ c, x1_max, ~, ~, ~, ~ ] = self.unpack_absolute_transmission_input_params( transmission_input_params, neuron_manager, undetected_option );
                
                % Pack the formulation params.
                formulation_input_params = self.pack_absolute_transmission_formulation_params( c, x1_max );
                
            elseif strcmpi( encoding_scheme, 'relative' )                   % If the encoding scheme is 'relative'...
                
                % Unpack the relative transmission params.
                [ c, x1_max, ~, ~, ~, ~ ] = self.unpack_relative_transmission_input_params( transmission_input_params, neuron_manager, undetected_option );
                
                % Pack the formulation params.
                formulation_input_params = self.pack_relative_transmission_formulation_params( c, x1_max );
                
            else                                                            % Otherwise...
                
                % Throw an error.
                error( 'Encoding scheme %s not recognized. Must be either ''absolute'' or ''relative.''\n', encoding_scheme )
                
            end
            
        end
            
        
        % Implement a function to convert transmission params to neuron params.
        function neuron_input_params = transmission_input_params2neuron_input_params( self, transmission_input_params, encoding_scheme, neuron_manager, undetected_option )
            
            % Set the default input arguments.
            if nargin < 5, undetected_option = self.undetected_option_DEFAULT; end
            if nargin < 4, neuron_manager = self.neuron_manager; end
            if nargin < 3, encoding_scheme = 'absolute'; end
            if nargin < 2, transmission_input_params = struct( [  ] ); end
            
            % Determine how to perform the parameter conversion.
            if strcmpi( encoding_scheme, 'absolute' )                       % If the encoding scheme is 'absolute'...

                % Unpack transmission params.
                [ c, x1_max, ~, ~, ~, ~ ] = self.unpack_absolute_transmission_input_params( transmission_input_params, neuron_manager, undetected_option );
                
                % Pack neuron params.
                neuron_input_params = neuron_manager.pack_absolute_transmission_params( c, x1_max );

            elseif strcmpi( encoding_scheme, 'relative' )                   % If the encoding scheme is 'relative'...
                                
                % Pack neuron params.
                neuron_input_params = struct( [  ] );
                
            else                                                            % Otherwise...
                
                % Throw an error.
                error( 'Encoding scheme %s not recognized. Must be either ''absolute'' or ''relative.''\n', encoding_scheme )
                
            end
                
        end
        
        
        % Implement a function to convert transmission params to synapse params.
        function synapse_input_params = transmission_input_params2synapse_input_params( self, transmission_input_params, encoding_scheme, neuron_manager, synapse_manager, undetected_option )
            
            % Set the default input arguments.
            if nargin < 6, undetected_option = self.undetected_option_DEFAULT; end
            if nargin < 5, synapse_manager = self.synapse_manager; end
            if nargin < 4, neuron_manager = self.neuron_manager; end
            if nargin < 3, encoding_scheme = 'absolute'; end
            if nargin < 2, transmission_input_params = struct( [  ] ); end
            
            % Determine how to perform the parameter conversion.
            if strcmpi( encoding_scheme, 'absolute' )                       % If the encoding scheme is 'absolute'...

                % Unpack transmission params.
                [ c, x1_max, ~, Gm2, ~, ~ ] = self.unpack_absolute_transmission_input_params( transmission_input_params, neuron_manager, undetected_option );

                % Pack synapse params.
                synapse_input_params = synapse_manager.pack_absolute_transmission_params( c, x1_max, Gm2 );
                
            elseif strcmpi( encoding_scheme, 'relative' )                   % If the encoding scheme is 'relative'...
                
                % Pack neuron params.
                [ ~, ~, ~, R2, ~, Gm2, ~, ~ ] = self.unpack_relative_transmission_input_params( transmission_input_params, neuron_manager, undetected_option );
                
                % Pack synapse params.
                synapse_input_params = synapse_manager.pack_relative_transmission_params( R2, Gm2 );
                
            else                                                            % Otherwise...
                
                % Throw an error.
                error( 'Encoding scheme %s not recognized. Must be either ''absolute'' or ''relative.''\n', encoding_scheme )
                
            end
            
        end
        
        
        % ---------- Addition Subnetwork Functions ----------
        
        % Implement a function to convert addition params to gain params.
        function gain_params = addition_params2gain_params( self, addition_params, encoding_scheme, neuron_manager, undetected_option )
            
            % Set the default input arguments.
            if nargin < 5, undetected_option = self.undetected_option_DEFAULT; end
            if nargin < 4, neuron_manager = self.neuron_manager; end
            if nargin < 3, encoding_scheme = 'absolute'; end
            if nargin < 2, addition_params = {  }; end
            
            % Determine how to perform the parameter conversion.
            if strcmpi( encoding_scheme, 'absolute' )                       % If the encoding scheme is 'absolute'...

                % Unpack the addition params.
                [ cs, ~, ~, ~ ] = self.unpack_absolute_addition_params( addition_params, neuron_manager, undetected_option );
                
                % Pack the gain params.
                gain_params = self.pack_absolute_addition_gain_params( cs );
                
            elseif strcmpi( encoding_scheme, 'relative' )                   % If the encoding scheme is 'relative'...
                
                % Unpack the addition params.
                [ cs_nm2, ~, ~, ~ ] = self.unpack_relative_addition_params( addition_params, neuron_manager, undetected_option );
                
                % Pack the gain params.
                gain_params = self.pack_relative_addition_gain_params( cs_nm2 );
                
            else                                                            % Otherwise...
                
                % Throw an error.
                error( 'Encoding scheme %s not recognized. Must be either ''absolute'' or ''relative.''\n', encoding_scheme )
                
            end
            
        end
        
        
        % Implement a function to convert addition params to neuron params.
        function neuron_params = addition_params2neuron_params( self, addition_params, encoding_scheme, neuron_manager, undetected_option )
            
            % Set the default input arguments.
            if nargin < 5, undetected_option = self.undetected_option_DEFAULT; end
            if nargin < 4, neuron_manager = self.neuron_manager; end
            if nargin < 3, encoding_scheme = 'absolute'; end
            if nargin < 2, addition_params = {  }; end
            
            % Determine how to perform the parameter conversion.
            if strcmpi( encoding_scheme, 'absolute' )                       % If the encoding scheme is 'absolute'...

                % Unpack transmission params.
                [ cs, Rs_input, ~, ~ ] = self.unpack_absolute_addition_params( addition_params, neuron_manager, undetected_option );
                
                % Pack neuron params.
                neuron_params = neuron_manager.pack_absolute_addition_params( cs, Rs_input, neuron_manager.neurons, undetected_option );
                
            elseif strcmpi( encoding_scheme, 'relative' )                   % If the encoding scheme is 'relative'...
                
                % Pack neuron params.
                neuron_params = {  };
                
            else                                                            % Otherwise...
                
                % Throw an error.
                error( 'Encoding scheme %s not recognized. Must be either ''absolute'' or ''relative.''\n', encoding_scheme )
                
            end
                
        end
        
        
        % Implement a function to convert addition params to synapse params.
        function synapse_params = addition_params2synapse_params( self, addition_params, design_params, encoding_scheme, neuron_manager, synapse_manager, applied_current_manager, undetected_option )
          
            % Set the default input arguments.
            if nargin < 8, undetected_option = self.undetected_option_DEFAULT; end
            if nargin < 7, applied_current_manager = self.applied_current_manager; end
            if nargin < 6, synapse_manager = self.synapse_manager; end
            if nargin < 5, neuron_manager = self.neuron_manager; end
            if nargin < 4, encoding_scheme = 'absolute'; end
            if nargin < 3, design_params = {  }; end
            if nargin < 2, addition_params = {  }; end
            
            % Determine how to perform the parameter conversion.
            if strcmpi( encoding_scheme, 'absolute' )                       % If the encoding scheme is 'absolute'...

                % Unpack addition params.
                [ cs, Rs_input, Gms, ~ ] = self.unpack_absolute_addition_params( addition_params, neuron_manager, undetected_option );
                                
                % Unpack design params.
                Ia_n = self.unpack_absolute_addition_synapse_design_params( design_params, neuron_manager, applied_current_manager, undetected_option );
                
                % Process the params.
                Gm_n = Gms( end );
                
                % Pack synapse params.                
                synapse_params = synapse_manager.pack_absolute_addition_params( cs, Rs_input, Gm_n, Ia_n );
                
            elseif strcmpi( encoding_scheme, 'relative' )                   % If the encoding scheme is 'relative'...
                
                % Unpack addition params.
                [ cs_nm1, Rs, Gms, ~ ] = self.unpack_relative_addition_params( addition_params, neuron_manager, undetected_option );
                
                % Unpack the design params.
                [ c_n, Ia_n ] = self.unpack_relative_addition_synapse_design_params( design_params, neuron_manager, applied_current_manager, undetected_option );
                
                % Process the params.
                cs = [ cs_nm1, c_n ];
                R_n = Rs( end );
                Gm_n = Gms( end );
                
                % Pack synapse params.
                synapse_params = synapse_manager.pack_relative_addition_params( cs, R_n, Gm_n, Ia_n );
                
            else                                                            % Otherwise...
                
                % Throw an error.
                error( 'Encoding scheme %s not recognized. Must be either ''absolute'' or ''relative.''\n', encoding_scheme )
                
            end
            
        end
        
        
