        end
        
        
        % Implement a function to convert subtraction params to synapse params.
        function synapse_params = subtraction_params2synapse_params( self, subtraction_params, design_params, encoding_scheme, neuron_manager, synapse_manager, applied_current_manager, undetected_option )
            
            % Set the default input arguments.
            if nargin < 8, undetected_option = self.undetected_option_DEFAULT; end
            if nargin < 7, applied_current_manager = self.applied_current_manager; end
            if nargin < 6, synapse_manager = self.synapse_manager; end
            if nargin < 5, neuron_manager = self.neuron_manager; end
            if nargin < 4, encoding_scheme = 'absolute'; end
            if nargin < 3, design_params = {  }; end
            if nargin < 2, subtraction_params = {  }; end
            
            % Determine how to perform the parameter conversion.
            if strcmpi( encoding_scheme, 'absolute' )                       % If the encoding scheme is 'absolute'...

                % Unpack subtraction params.
                [ cs, ss, Rs_input, Gms, ~ ] = self.unpack_absolute_subtraction_params( subtraction_params, neuron_manager, undetected_option );
                
                % Unpack the design params.
                Ia_n = self.unpack_absolute_subtraction_synapse_design_params( design_params, neuron_manager, applied_current_manager, undetected_option );
                
                % Process the params.
                Gm_n = Gms( end );
                
                % Pack synapse params.                                
                synapse_params = synapse_manager.pack_absolute_subtraction_params( cs, ss, Rs_input, Gm_n, Ia_n );
                
            elseif strcmpi( encoding_scheme, 'relative' )                 	% If the encoding scheme is 'relative'...
                
                % Unpack subtraction params.
                [ cs_mn1, ss, Rs, Gms, ~ ] = self.unpack_relative_subtraction_params( subtraction_params, neuron_manager, undetected_option );
                
                % Unpack the design params.
                [ c_n, Ia_n ] = self.unpack_relative_subtraction_synapse_design_params( design_params, neuron_manager, applied_current_manager, undetected_option );
                
                % Process the params.
                cs = [ cs_mn1, c_n ];
                Rs_input = Rs( 1:( end - 1 ) );
                Gm_n = Gms( end );
                
                % Pack synapse params.
                synapse_params = synapse_manager.pack_relative_subtraction_params( cs, ss, Rs_input, Gm_n, Ia_n );
                
            else                                                          	% Otherwise...
                
                % Throw an error.
                error( 'Encoding scheme %s not recognized. Must be either ''absolute'' or ''relative.''\n', encoding_scheme )
                
            end
            
        end
        
        
