                [ c1, c3, delta1, ~, R1, ~, ~, ~, ~, ~, ~, ~, ~, ~ ] = self.unpack_reduced_absolute_multiplication_params( reduced_multiplication_params, neuron_manager, undetected_option );

                % Retrieve the design params.
                [ c2, c4 ] = self.unpack_reduced_absolute_multiplication_neuron_design_params( design_params );
                
                % Pack neuron params.                
                neuron_params = neuron_manager.pack_reduced_absolute_multiplication_params( c1, c2, c3, c4, delta1, R1, neuron_manager.neurons, undetected_option );
                
            elseif strcmpi( encoding_scheme, 'relative' )                   % If the encoding scheme is 'relative'...
                
                % Pack neuron params.
                neuron_params = {  };
                
            else                                                            % Otherwise...
                
                % Throw an error.
                error( 'Encoding scheme %s not recognized. Must be either ''absolute'' or ''relative.''\n', encoding_scheme )
                
            end
                
        end
        
        
        % Implement a function to convert reduced multiplication params to synapse params.
        function synapse_params = reduced_multiplication_params2synapse_params( self, reduced_multiplication_params, design_params, encoding_scheme, neuron_manager, synapse_manager, applied_current_manager, undetected_option )
            
            % Set the default input arguments.
            if nargin < 8, undetected_option = self.undetected_option_DEFAULT; end
            if nargin < 7, applied_current_manager = self.applied_current_manager; end
            if nargin < 6, synapse_manager = self.synapse_manager; end
            if nargin < 5, neuron_manager = self.neuron_manager; end
            if nargin < 4, encoding_scheme = 'absolute'; end
            if nargin < 3, design_params = {  }; end
            if nargin < 2, reduced_multiplication_params = {  }; end
            
            % Determine how to perform the parameter conversion.
            if strcmpi( encoding_scheme, 'absolute' )                       % If the encoding scheme is 'absolute'...

                % Unpack multiplication params.                                                
                [ ~, ~, delta1, delta2, ~, ~, ~, ~, Gm3, Gm4, ~, ~, ~, ~ ] = self.unpack_reduced_absolute_multiplication_params( reduced_multiplication_params, neuron_manager, undetected_option );
                
                % Retrieve the design params.
                [ R3, R4, Ia3 ] = self.unpack_reduced_absolute_mult_synapse_design_params( design_params, neuron_manager, applied_current_manager, undetected_option );
                
                % Pack synapse params.
                synapse_params = synapse_manager.pack_reduced_absolute_multiplication_params( delta1, delta2, R3, R4, Gm3, Gm4, Ia3 );
                
            elseif strcmpi( encoding_scheme, 'relative' )                   % If the encoding scheme is 'relative'...
                
                % Unpack multiplication params.
                [ delta1, delta2, ~, ~, R3, R4, ~, ~, Gm3, Gm4, ~, ~, ~, ~ ] = self.unpack_reduced_relative_multiplication_params( reduced_multiplication_params, neuron_manager, undetected_option );
                
                % Retrieve the design params.
                Ia3 = self.unpack_reduced_relative_mult_synapse_design_params( design_params, neuron_manager, applied_current_manager, undetected_option );
                
                % Pack synapse params.
                synapse_params = synapse_manager.pack_reduced_relative_multiplication_params( delta1, delta2, R3, R4, Gm3, Gm4, Ia3 );
                
            else                                                            % Otherwise...
                
                % Throw an error.
                error( 'Encoding scheme %s not recognized. Must be either ''absolute'' or ''relative.''\n', encoding_scheme )
                
            end
            
        end
        
        
