        %% Subnetwork Design Functions.
        
        % ---------- Transmission Subnetwork Functions ----------
        
        % Implement a function to design a transmission subnetwork using existing neurons.
        function [ transmission_output_params, neurons, synapses, neuron_manager, synapse_manager, self ] = design_transmission_subnetwork( self, neuron_IDs, transmission_input_params, encoding_scheme, neuron_manager, synapse_manager, applied_current_manager, set_flag, validation_flag, undetected_option )
            
            % Absolute:
                % transmission_input_params = { c, x1_max, Gm1, Gm2, Cm1, Cm2 };
                % transmission_output_params = { x2_max, R1, R2, Gna1, Gna2, gs21, dEs21, Ia2 }
            
            % Relative:
                % transmission_input_params = { c, x1_max, R1, R2, Gm1, Gm2, Cm1, Cm2 };
                % transmission_output_params = { x2_max, Gna1, Gna2, gs21, dEs21, Ia2 }
                
            % Set the default input arguments.
            if nargin < 10, undetected_option = self.undetected_option_DEFAULT; end                                   	% [str] Undetected Option.
            if nargin < 9, validation_flag = self.validation_flag_DEFAULT; end                                          % [T/F] Validation Flag.
            if nargin < 8, set_flag = self.set_flag_DEFAULT; end                                                        % [T/F] Set Flag.
            if nargin < 7, applied_current_manager = self.applied_current_manager; end                                  % [class] Applied Current Manager Class.
            if nargin < 6, synapse_manager = self.synapse_manager; end                                                  % [class] Synapse Manager Class.
            if nargin < 5, neuron_manager = self.neuron_manager; end                                                    % [class] Neuron Manager Class.
            if nargin < 4, encoding_scheme = self.encoding_scheme_DEFAULT; end                                          % [str] Encoding Scheme (Must be either: 'absolute' or 'relative'.)
            if nargin < 3, transmission_input_params = struct( [  ] ); end                                      	% [-] Parameters Cell.
            
            % ENSURE THAT THE GIVEN NEURONS DO IN FACT HAVE THE NECESSARY SYNAPTIC CONNECTIONS BEFORE PROCEEDING.  OTHERWISE THROW AN ERROR.
            
            % Create an instance of the network object.
            network = self;
              
            
            % -------------------- Formulation Design --------------------
            
            % Convert the transmission params to formulation params.
            formulation_input_params = self.transmission_input_params2formulation_input_params( transmission_input_params, encoding_scheme, neuron_manager, undetected_option );
            
            % Design the subnetwork formulation.
            formulation_output_params = self.design_transmission_formulation( formulation_input_params, encoding_scheme );
            
            
            % -------------------- Neuron Design --------------------
            
            % Convert subnetwork params to neuron params.
            neuron_input_params = network.transmission_input_params2neuron_input_params( transmission_input_params, encoding_scheme, neuron_manager, undetected_option );
            
            % Design the subnetwork neurons.
            [ neuron_output_params, neurons, neuron_manager, network ] = network.design_transmission_neurons( neuron_IDs, neuron_input_params, encoding_scheme, neuron_manager, true, undetected_option );
            
            
            % -------------------- Applied Current Design --------------------
            
            % Design the subnetwork applied currents.
            applied_current_output_params = self.design_transmission_applied_current( encoding_scheme, applied_current_manager );
               
            
            % -------------------- Synapse Design --------------------
            
            % Convert subnetwork params to synapse params.
            synapse_input_params = network.transmission_input_params2synapse_input_params( transmission_input_params, encoding_scheme, neuron_manager, synapse_manager, undetected_option );
            
            % Design the subnetwork subnetwork synapses.
            [ synapse_output_params, ~, synapses, synapse_manager, network ] = network.design_transmission_synapse( neuron_IDs, synapse_input_params, encoding_scheme, synapse_manager, true, validation_flag, undetected_option );
            
            
            % -------------------- Output Processing --------------------

            % Concatenate the output cells.            
            transmission_output_params = self.numerical_method_utilities.concatenate_structures( { formulation_output_params, neuron_output_params, synapse_output_params, applied_current_output_params } );
            
            % Determine whether to update the network object.
            if set_flag, self = network; end
            
        end
        
        
        % ---------- Addition Subnetwork Functions ----------
        
        % Implement a function to design an addition subnetwork ( using the specified neurons, synapses, and applied currents ).
        function [ cs, Gnas, Rn, dEs, gs, Ia_n, neurons, synapses, neuron_manager, synapse_manager, self ] = design_addition_subnetwork( self, neuron_IDs, addition_params, encoding_scheme, neuron_manager, synapse_manager, applied_current_manager, set_flag, validation_flag, undetected_option )
            
            % Set the default input arguments.
            if nargin < 10, undetected_option = self.undetected_option_DEFAULT; end                           	% [str] Undetected Option.
            if nargin < 9, validation_flag = self.validation_flag_DEFAULT; end                                  % [T/F] Validation Flag.
            if nargin < 8, set_flag = self.set_flag_DEFAULT; end                                               	% [T/F] Set Flag.
            if nargin < 7, applied_current_manager = self.applied_current_manager; end                          % [class] Applied Current Manager Class.
            if nargin < 6, synapse_manager = self.synapse_manager; end                                         	% [class] Synapse Manager Class.
            if nargin < 5, neuron_manager = self.neuron_manager; end                                          	% [class] Neuron Manager Class.
            if nargin < 4, encoding_scheme = self.encoding_scheme_DEFAULT; end                               	% [str] Encoding Scheme (Must be either: 'absolute' or 'relative'.)
            if nargin < 3, addition_params = {  }; end                                                    	% [-] Parameters Cell.
            
            % ENSURE THAT THE GIVEN NEURONS DO IN FACT HAVE THE NECESSARY SYNAPTIC CONNECTIONS BEFORE PROCEEDING.  OTHERWISE THROW AN ERROR.
            
            % Create an instance of the network object.
            network = self;
            
            
            % -------------------- Gain Design --------------------
            
            % Convert the addition params to gain params.
            gain_params = self.addition_params2gain_params( addition_params, encoding_scheme, neuron_manager, undetected_option );
            
            % Compute the addition subnetwork gains.
            cs = self.compute_addition_cs( gain_params, encoding_scheme );
            
            
            % -------------------- Neuron Design --------------------
            
            % Convert subnetwork params to neuron params.
            neuron_params = network.addition_params2neuron_params( addition_params, encoding_scheme, neuron_manager, undetected_option );
            
            % Design the addition subnetwork neurons.
            [ Gnas, Rn, neurons, neuron_manager, network ] = network.design_addition_neurons( neuron_IDs, neuron_params, encoding_scheme, neuron_manager, true, undetected_option );
            
            
            % -------------------- Applied Current Design --------------------
            
            % Design the subnetwork applied currents.
            Ia_n = self.design_addition_applied_current( encoding_scheme, applied_current_manager );
            
            
            % -------------------- Synapse Design --------------------
            
            % Determine how to pack the design params.
            if strcmpi( encoding_scheme, 'absolute' )               % If the encoding scheme is 'absolute'...

                % Pack the design params.                
                synapse_design_params = self.pack_absolute_addition_synapse_design_params( Ia_n, neuron_manager, applied_current_manager, undetected_option );
                
            elseif strcmpi( encoding_scheme, 'relative' )           % If the encoding scheme is 'relative'...
                
                % Pack the design params.                
                synapse_design_params = self.pack_relative_addition_synapse_design_params( cs( end ), Ia_n, neuron_manager, applied_current_manager, undetected_option );
                
            else                                                    % Otherwise...
                
                % Throw an error.
                error( 'Unrecognized encoding scheme.' )
                
            end 
            
            % Convert subnetwork params to synapse params.
            synapse_params = network.addition_params2synapse_params( addition_params, synapse_design_params, encoding_scheme, neuron_manager, synapse_manager, undetected_option );
            
            % Design the addition subnetwork synapses.
            [ dEs, gs, ~, synapses, synapse_manager, network ] = network.design_addition_synapses( neuron_IDs, synapse_params, encoding_scheme, synapse_manager, true, validation_flag, undetected_option );
            
            % Determine whether to update the network object.
            if set_flag, self = network; end
            
        end
        
        
