            gain_params = self.reduced_multiplication_params2gain_params( reduced_multiplication_params, gain_design_params, encoding_scheme, neuron_manager, undetected_option );
            
            % Compute the subnetwork gains.
            [ c1, c2, c3, c4 ] = self.compute_reduced_multiplication_cs( gain_params, encoding_scheme );
            
            % Store the subnetwork gains in an array.
            cs = [ c1, c2, c3, c4 ];
            
            
            % -------------------- Neuron Design --------------------
            
            % Pack the neuron design params.
            if strcmpi( encoding_scheme, 'absolute' )               % If the encoding scheme is 'absolute'...

                % Pack the design params.
                neuron_design_params = self.pack_reduced_absolute_multiplication_neuron_design_params( c2, c4 );
                
            elseif strcmpi( encoding_scheme, 'relative' )           % If the encoding scheme is 'relative'...
                
                % Pack the design params.                
                neuron_design_params = self.pack_reduced_relative_multiplication_neuron_design_params(  );
                
            else                                                    % Otherwise...
                
                % Throw an error.
                error( 'Unrecognized encoding scheme.' )
                
            end  
            
            % Convert subnetwork params to neuron params.            
            neuron_params = network.reduced_multiplication_params2neuron_params( reduced_multiplication_params, neuron_design_params, encoding_scheme, neuron_manager, undetected_option );
            
            % Design the multiplication subnetwork neurons.                                                
            [ Gnas, Rs, neurons, neuron_manager, network ] = network.design_reduced_multiplication_neurons( neuron_IDs, neuron_params, encoding_scheme, neuron_manager, true, undetected_option );
            
            
            % -------------------- Applied Current Design --------------------
            
            % Pack the applied current design params.
            if strcmpi( encoding_scheme, 'absolute' )               % If the encoding scheme is 'absolute'...

                % Pack the design params.                                
                applied_current_design_params = self.pack_reduced_absolute_mult_app_current_design_params( R3, neuron_manager, undetected_option );
                
            elseif strcmpi( encoding_scheme, 'relative' )           % If the encoding scheme is 'relative'...
                
                % Pack the design params.                
                applied_current_design_params = self.pack_reduced_relative_mult_app_current_design_params(  );
                
            else                                                    % Otherwise...
                
                % Throw an error.
                error( 'Unrecognized encoding scheme.' )
                
            end 
            
            % Convert subnetwork params to applied current params.            
            applied_current_params = network.reduced_multiplication_params2applied_current_params( reduced_multiplication_params, applied_current_design_params, encoding_scheme, neuron_manager, applied_current_manager, undetected_option );
            
            % Design the multiplication subnetwork applied currents.                                    
            [ Ias3, applied_currents, applied_current_manager, network ] = network.design_reduced_multiplication_applied_current( neuron_IDs, applied_current_params, encoding_scheme, applied_current_manager, true, undetected_option );
                        
            
            % -------------------- Synapse Design --------------------
            
            % Pack the synapse design params.
            if strcmpi( encoding_scheme, 'absolute' )               % If the encoding scheme is 'absolute'...

                % Pack the design params.                
                synapse_design_params = self.pack_reduced_absolute_multiplication_synapse_design_params( R3, R4, Ia3, neuron_manager, applied_current_manager, undetected_option );
                
            elseif strcmpi( encoding_scheme, 'relative' )           % If the encoding scheme is 'relative'...
                
                % Pack the design params.                
                synapse_design_params = self.pack_reduced_relative_multiplication_synapse_design_params( Ia3, neuron_manager, applied_current_manager, undetected_option );
                
            else                                                    % Otherwise...
                
                % Throw an error.
                error( 'Unrecognized encoding scheme.' )
                
            end 
            
            % Convert subnetwork params to synapse params.            
            synapse_params = network.reduced_multiplication_params2synapse_params( reduced_multiplication_params, synapse_design_params, encoding_scheme, neuron_manager, synapse_manager, undetected_option );
            
            % Design the multiplication subnetwork synapses.            
            [ dEs, gs, ~, synapses, synapse_manager, network ] = network.design_reduced_multiplication_synapses( neuron_IDs, synapse_params, encoding_scheme, synapse_manager, true, validation_flag, undetected_option );
            
            % Determine whether to update the network object.
            if set_flag, self = network; end
            
        end
        
        
