        % Implement a function to convert transmission design params to network params.
        function [ neuron_input_params, synapse_input_params ] = transmission_params2network_params( self, transmission_input_params, encoding_scheme, neuron_manager, synapse_manager, undetected_option )
            
            % Set the default input arguments.
            if nargin < 6, undetected_option = self.undetected_option_DEFAULT; end
            if nargin < 5, synapse_manager = self.synapse_manager; end
            if nargin < 4, neuron_manager = self.neuron_manager; end
            if nargin < 3, encoding_scheme = self.encoding_scheme_DEFAULT; end
            
            % Determine how to convert transmission design params to network params.
            if strcmpi( encoding_scheme, 'absolute' )               % If the encoding scheme is 'absolute'...
        
                % Ensure that the transmission params have been defined.
                if nargin < 2, transmission_input_params = self.pack_absolute_transmission_input_params(  ); end

                % Convert absolue transmission params to network params.
                [ neuron_input_params, synapse_input_params ] = self.absolute_transmission_params2network_params( transmission_input_params, neuron_manager, synapse_manager, undetected_option );
            
            elseif strcmpi( encoding_scheme, 'relative' )            % If the encoding scheme is 'relative'...
                
                % Ensure that the transmission params have been defined.
                if nargin < 2, transmission_input_params = self.pack_relative_transmission_input_params(  ); end
                
                % Convert relative transmission params to network params.
                [ neuron_input_params, synapse_input_params ] = self.relative_transmission_params2network_params( transmission_input_params, neuron_manager, synapse_manager, undetected_option );
                
            else                                                    % Otherwise...
                
                % Throw an error.
                error( 'Invalid encoding scheme.  Must be either: ''absolute'' or ''relative''.' )
                
            end
            
        end
        
        
