                % Ensure that the subtraction params have been defined.
                if nargin < 2, subtraction_params = self.pack_absolute_subtraction_params(  ); end
                
                % Convert absolue subtraction params to network params.
                [ neuron_params, synapse_params ] = self.absolute_subtraction_params2network_params( subtraction_params, neuron_manager, synapse_manager, undetected_option );
            
            elseif strcmpi( encoding_scheme, 'relative' )            % If the encoding scheme is 'relative'...
                
                % Ensure that the subtraction params have been defined.
