        % Implement a function to convert multiplication design params to network params.
        function [ neuron_params, synapse_params, applied_current_params ] = multiplication_params2network_params( self, multiplication_params, encoding_scheme, neuron_manager, synapse_manager, applied_current_manager, undetected_option )

            % Set the default input arguments.
            if nargin < 7, undetected_option = self.undetected_option_DEFAULT; end
            if nargin < 6, applied_current_manager = self.applied_current_manager; end
            if nargin < 5, synapse_manager = self.synapse_manager; end
            if nargin < 4, neuron_manager = self.neuron_manager; end
            if nargin < 3, encoding_scheme = self.encoding_scheme_DEFAULT; end
            
            % Determine how to convert multiplication design params to network params.
            if strcmpi( encoding_scheme, 'absolute' )               % If the encoding scheme is 'absolute'...
        
                % Ensure that the multiplication params have been defined.
                if nargin < 2, multiplication_params = self.pack_absolute_multiplication_params(  ); end
                
                % Convert absolue multiplication params to network params.
                [ neuron_params, synapse_params, applied_current_params ] = self.absolute_multiplication_params2network_params( multiplication_params, neuron_manager, synapse_manager, applied_current_manager, undetected_option );
            
            elseif strcmpi( encoding_scheme, 'relative' )          	% If the encoding scheme is 'relative'...
                
                % Ensure that the multiplication params have been defined.
                if nargin < 2, multiplication_params = self.pack_relative_multiplication_params(  ); end
                
                % Convert relative multiplication params to network params.
                [ neuron_params, synapse_params, applied_current_params ] = self.relative_multiplication_params2network_params( multiplication_params, neuron_manager, synapse_manager, applied_current_manager, undetected_option );
                
            else                                                    % Otherwise...
                
                % Throw an error.
                error( 'Invalid encoding scheme.  Must be either: ''absolute'' or ''relative''.' )
                
            end
            
        end
        
        
