        %{
        % Implement a function to create the modulation subnetwork components.
        function [ neuron_output_params, synapse_output_params, self ] = create_modulation_subnetwork_components( self, neuron_input_params, synapse_input_params, neuron_manager, synapse_manager, set_flag, as_cell_flag )
            
            % Set the default input arguments.
            if nargin < 7, as_cell_flag = self.as_cell_flag_DEFAULT; end
            if nargin < 6, set_flag = self.set_flag_DEFAULT; end                                                        % [T/F] Set Flag.
            if nargin < 5, synapse_manager = self.synapse_manager; end                                                  % [class] Synapse Manager Class.
            if nargin < 4, neuron_manager = self.neuron_manager; end                                                    % [class] Neuron Manager Class.
            if nargin < 3, synapse_input_params = self.pack_synapse_input_params(  ); end
            if nargin < 2, neuron_input_params = self.pack_neuron_input_params(  ); end
            
            % Unpack neuron and synapse input params.
            [ neuron_IDs, neuron_names, Us, hs, Cms, Gms, Ers, Rs, Ams, Sms, dEms, Ahs, Shs, dEhs, dEnas, tauh_maxs, Gnas, I_leaks, I_syns, I_nas, I_tonics, I_apps, I_totals, neuron_enabled_flags ] = self.unpack_neuron_input_params( neuron_input_params );
            [ synapse_ID, synapse_name, dEs, gs, from_neuron_ID, to_neuron_ID, delta, synapse_enabled_flag ] = self.unpack_synapse_input_params( synapse_input_params );
            
            % Create the modulation neurons and synapses.            
            [ neuron_IDs_new, neurons_new, neurons, neuron_manager ] = neuron_manager.create_modulation_neurons( encoding_scheme, neuron_IDs, neuron_names, Us, hs, Cms, Gms, Ers, Rs, Ams, Sms, dEms, Ahs, Shs, dEhs, dEnas, tauh_maxs, Gnas, I_leaks, I_syns, I_nas, I_tonics, I_apps, I_totals, neuron_enabled_flags, neuron_manager.neurons, true, as_cell_flag, neuron_manager.array_utilities );
            [ synapse_ID_new, synapse_new, synapses, synapse_manager ] = synapse_manager.create_modulation_synapse( neuron_IDs, synapse_ID, synapse_name, dEs, gs, from_neuron_ID, to_neuron_ID, delta, synapse_enabled_flag, synapse_manager.synapses, true, as_cell_flag, array_utilities );
            
            % Pack the neuron and synapse output params.
            neuron_output_params = self.pack_neuron_output_params( neuron_IDs_new, neurons_new, neurons, neuron_manager );
            synapse_output_params = self.pack_synapse_output_params( synapse_ID_new, synapse_new, synapses, synapse_manager );
            
            % Determine whether to update the network object.
            if set_flag                                                     % If we want to update the network object...
                
                % Update the neuron and synapse manager.
                self.neuron_manager = neuron_manager;
                self.synapse_manager = synapse_manager;
                
            end
            
        end
        %}
        
        
        %% Subnetwork Creation Functions.
        
        % ---------- Transmission Subnetwork Functions ----------

        % Implement a function to create a transmission subnetwork ( generating neurons, synapses, etc. as necessary ).
        function [ transmission_output_params, neurons, synapses, neuron_manager, synapse_manager, self ] = create_transmission_subnetwork( self, transmission_input_params, encoding_scheme, neuron_manager, synapse_manager, applied_current_manager, set_flag, validation_flag, as_cell_flag, undetected_option )
            
            % transmission_input_params = { c, x1_max, Gm1, Gm2, Cm1, Cm2 };
            % transmission_output_params = { x2_max, Gnas, R2, dEs21, gs21, Ia2 }
            
            % Set the default input arguments.
            if nargin < 10, undetected_option = self.undetected_option_DEFAULT; end                                    	% [str] Undetected Option.
            if nargin < 9, as_cell_flag = self.as_cell_flag_DEFAULT; end                                                % [T/F] As Cell Flag.
            if nargin < 8, validation_flag = self.validation_flag_DEFAULT; end                                          % [T/F] Validation Flag.
            if nargin < 7, set_flag = self.set_flag_DEFAULT; end                                                        % [T/F] Set Flag.
            if nargin < 6, applied_current_manager = self.applied_current_manager; end                                  % [class] Applied Current Manager Class.
            if nargin < 5, synapse_manager = self.synapse_manager; end                                                  % [class] Synapse Manager Class.
            if nargin < 4, neuron_manager = self.neuron_manager; end                                                    % [class] Neuron Manager Class.
            if nargin < 3, encoding_scheme = self.encoding_scheme_DEFAULT; end                                          % [str] Encoding Scheme (Must be either: 'absolute' or 'relative'.)
            % if nargin < 2, transmission_input_params = self.pack_transmission_params( encoding_scheme ); end   	% [-] Transmission Parameters.

            % Create an instance of the network object.
            network = self;
                        
          	% Convert the transmission params to network params.
            [ neuron_input_params, synapse_input_params ] = network.transmission_params2network_params( transmission_input_params, encoding_scheme, neuron_manager, synapse_manager, undetected_option );
                        
            % Create the transmission subnetwork components.
            [ neuron_output_params, synapse_output_params, network ] = network.create_transmission_subnetwork_components( neuron_input_params, synapse_input_params, encoding_scheme, neuron_manager, synapse_manager, true, as_cell_flag );
                                  
            % Unpack the neuron, synapse, and applied current properties.
            [ neuron_IDs, ~, ~, neuron_manager ] = self.unpack_neuron_output_params( neuron_output_params );
            [ ~, ~, ~, synapse_manager ] = self.unpack_synapse_output_params( synapse_output_params );

            % Design a transmission subnetwork.
            [ transmission_output_params, neurons, synapses, neuron_manager, synapse_manager, network ] = network.design_transmission_subnetwork( neuron_IDs, transmission_input_params, encoding_scheme, neuron_manager, synapse_manager, applied_current_manager, true, validation_flag, undetected_option );
              
            % Determine whether to update the network object.
            if set_flag, self = network; end
            
        end
        
        
        % ---------- Addition Subnetwork Functions ----------
       
        % Implement a function to create an addition subnetwork ( generating neurons, synapses, etc. as necessary ).
        function [ cs, Gnas, Rn, dEs, gs, Ia_n, neurons, synapses, neuron_manager, synapse_manager, self ] = create_addition_subnetwork( self, addition_params, encoding_scheme, neuron_manager, synapse_manager, applied_current_manager, set_flag, validation_flag, as_cell_flag, undetected_option )
            
            % Set the default input arguments.
            if nargin < 10, undetected_option = self.undetected_option_DEFAULT; end                                                 % [str] Undetected Option.
            if nargin < 9, as_cell_flag = self.as_cell_flag_DEFAULT; end                                                            % [T/F] As Cell Flag.
            if nargin < 8, validation_flag = self.validation_flag_DEFAULT; end                                                      % [T/F] Validation Flag.
            if nargin < 7, set_flag = self.set_flag_DEFAULT; end                                                                    % [T/F] Set Flag.
            if nargin < 6, applied_current_manager = self.applied_current_manager; end                                              % [class] Applied Current Manager Class.
            if nargin < 5, synapse_manager = self.synapse_manager; end                                                              % [class] Synapse Manager Class.
            if nargin < 4, neuron_manager = self.neuron_manager; end                                                                % [class] Neuron Manager Class.
            if nargin < 3, encoding_scheme = self.encoding_scheme_DEFAULT; end                                                      % [str] Encoding Scheme (Must be either: 'absolute' or 'relative'.)
            if nargin < 2, addition_params = self.pack_addition_params( self.n_addition_DEFAULT, encoding_scheme ); end     % [-] Addition Parameters.

            % Create an instance of the network object.
            network = self;
            
            % Convert the addition params into network params.
            [ neuron_input_params, synapse_input_params ] = network.addition_params2network_params( addition_params, encoding_scheme, neuron_manager, synapse_manager, undetected_option );
            
            % Create addition subnetwork components.
            [ neuron_output_params, synapse_output_params, network ] = network.create_addition_subnetwork_components( neuron_input_params, synapse_input_params, neuron_manager, synapse_manager, true, as_cell_flag );
                                    
            % Unpack the neuron, synapse, and applied current properties.
            neuron_IDs = neuron_output_params{ 1 };
            neuron_manager = neuron_output_params{ 4 };
            synapse_manager = synapse_output_params{ 4 };
            
            % Design the addition subnetwork.
            [ cs, Gnas, Rn, dEs, gs, Ia_n, neurons, synapses, neuron_manager, synapse_manager, network ] = network.design_addition_subnetwork( neuron_IDs, addition_params, encoding_scheme, neuron_manager, synapse_manager, applied_current_manager, true, validation_flag, undetected_option );
                                     
            % Determine whether to update the network object.
            if set_flag, self = network; end
            
        end
                
        
